import java.io.*;
import java.util.*;
/** Room adapter for the shared four-stage campaign. Ant Cave and PvP keep their routes. */
final class TribalDungeon {
 static boolean isRoom(GunnyServer server,int id){var r=server.rooms.get(id);return r!=null&&is(r);}
 static boolean is(GunnyServer.Room r){return r.kind==3&&r.dungeonStage>=3;}
 static void eligible(GunnyServer.Session s,int difficulty){GunnyServer.requireWeapon(s);if(!s.tribal)throw new IllegalArgumentException("Cập nhật game để vào Bộ Lạc Tà Thần");if(difficulty<0||difficulty>2||Progression.level(s.profile.experience)<TribalRules.minLevel)throw new IllegalArgumentException("Bộ Lạc Tà Thần yêu cầu Lv "+TribalRules.minLevel);}
 static void handle(GunnyServer server,String op,GunnyServer.Session s,DataInputStream in,DataOutputStream out)throws Exception {
  if(!s.tribal)throw new IllegalArgumentException("Cập nhật game để chơi Bộ Lạc Tà Thần");
  if(op.equals("tribalwing")){if(s.room!=0)throw new IllegalArgumentException("Rời phòng trước khi thay cánh");server.store.tribal("wing",Map.of("user",s.id,"equip",in.readBoolean()));s.profile=server.store.profile(s.id);Expansion780.write(out,s.profile);return;}
  if(op.equals("tribalresume")){GunnyServer.Room room=server.rooms.get(s.room);boolean active=room!=null&&is(room);out.writeBoolean(active);if(active)server.lobby(out,room,s);return;}
  if(op.equals("tribalcreate")){int difficulty=in.readUnsignedByte();String name=GunnyServer.validRoomName(in.readUTF()),secret=in.readUTF();eligible(s,difficulty);server.store.tribal("status",Map.of());if(secret.length()>16)throw new IllegalArgumentException("Mật mã tối đa 16 ký tự");synchronized(server.rooms){if(server.rooms.size()>=server.maxRooms)throw new IllegalArgumentException("Hết phòng trống");server.leave(s);var room=server.new Room(s,6,2,-1,true);room.kind=3;room.dungeonStage=3;room.difficulty=difficulty;room.title=name;room.secret=secret;room.strict=true;room.seconds=15;room.mapLimit=12;room.refreshWaiting();server.rooms.put(room.id,room);s.room=room.id;server.lobby(out,room,s);}return;}
  var r=server.requireRoom(s);synchronized(r){if(!is(r))throw new IllegalArgumentException("Không phải Bộ Lạc Tà Thần");if(op.equals("tribalsettings")){int difficulty=in.readUnsignedByte();if(r.host!=s||r.phase!=0||r.dungeonStage!=3)throw new IllegalArgumentException("Chỉ chọn độ khó trước ải 1");for(var member:r.members)if(member!=null)eligible(member,difficulty);r.difficulty=difficulty;r.clearArmed();server.lobby(out,r,s);return;}}
  throw new IllegalArgumentException("Sai thao tác Bộ Lạc Tà Thần");
 }
 static void waiting(GunnyServer.Room r){for(int i=0;i<6;i++){var a=r.avatars[i];if(i%2==1){a.name=r.battle==null?"Bộ Lạc Tà Thần":TribalRules.name(r.battle.units[i].npc);a.bot=true;a.owner=null;}else if(r.members[i]==null){a.name="Đang chờ";a.bot=false;a.owner=null;}}}
 static void begin(GunnyServer.Room r){if(r.dungeonStage==3)r.campaignId=UUID.randomUUID().toString();for(int i=0;i<6;i+=2)if(r.members[i]==null){r.battle.units[i].hp=0;r.battle.units[i].dead=true;}TribalRules.setup(r.battle,r.dungeonStage-2,r.difficulty,r.beanSaved);waiting(r);checkpoint(r);}
 static void progress(GunnyServer.Room r){if(r.battle.dungeonStage==4&&r.battle.winner==0)r.beanSaved=true;if(r.battle.over){r.savedTribalTurn=-2;checkpoint(r);return;}if(r.savedTribalTurn!=r.battle.turn){r.savedTribalTurn=r.battle.turn;checkpoint(r);}}
 static Map<String,Object> state(GunnyServer.Room r){List<Object> units=new ArrayList<>();for(var u:r.battle.units)units.add(List.of(u.npc,u.x,u.y,u.hp,u.maxHp,u.dead));return Map.of("turn",r.battle.turn,"round",r.battle.tribalRound,"phase",r.battle.tribalPhase,"wave",r.battle.tribalWave,"active",r.battle.active,"units",units,"bean",r.beanSaved,"over",r.battle.over,"winner",r.battle.winner);}
 static void checkpoint(GunnyServer.Room r){String run=r.campaignId;int stage=r.dungeonStage-2,difficulty=r.difficulty,turn=r.battle.turn;List<String> members=new ArrayList<>();for(var m:r.members)if(m!=null)members.add(m.id);var state=state(r);r.savesTribal(run,stage,difficulty,turn,members,state);}
 static void settle(GunnyServer server,GunnyServer.Room r,List<Map<String,Object>> players)throws Exception {var payload=new HashMap<String,Object>();payload.put("match",r.match);payload.put("run",r.campaignId);payload.put("stage",r.dungeonStage-2);payload.put("difficulty",r.difficulty);payload.put("winner",r.battle.winner);payload.put("players",players);payload.put("min",TribalRules.STONE_MIN[r.difficulty]);payload.put("max",TribalRules.STONE_MAX[r.difficulty]);server.store.tribal("finish",payload);}
 static int[] claim(GunnyServer server,GunnyServer.Room r,String id,int pick,int card)throws Exception {var result=server.store.tribal("claim",Map.of("match",r.match,"user",id,"pick",pick,"card",card));return new int[]{Json.num(result,"card",-1),Json.num(result,"type",0),Json.num(result,"amount",0),Json.num(result,"pick",-1)};}
 static boolean reconnect(GunnyServer server,GunnyServer.Session old,GunnyServer.Session fresh){var r=server.rooms.get(old.room);if(r==null||!is(r)||!fresh.tribal)return false;synchronized(r){int seat=r.slot(old);if(seat<0)return false;r.members[seat]=fresh;r.avatars[seat].owner=fresh;if(r.host==old)r.host=fresh;fresh.room=r.id;fresh.sequence=0;fresh.held=0;fresh.ready=false;fresh.armed=old.armed;fresh.resolution=-1;r.lastActive=System.currentTimeMillis();return true;}}
}
